let i18nLanguage = "en";

function i18nSetLanguage(value) {
  i18nLanguage = Object.hasOwn(I18N_CATALOGS, value) ? value : "en";
  document.documentElement.lang = i18nLanguage;
}

function i18nTranslate(key, variables = {}) {
  const template = I18N_CATALOGS[i18nLanguage]?.[key] ?? I18N_CATALOGS.en[key] ?? key;
  return template.replace(/\{([a-zA-Z0-9_]+)\}/g, (_match, name) => String(variables[name] ?? ""));
}

function i18nSource(value) {
  const exact = SOURCE_TRANSLATIONS[i18nLanguage]?.[value] ?? MODEL_TRANSLATIONS[i18nLanguage]?.[value] ?? PLUGIN_TRANSLATIONS[i18nLanguage]?.[value] ?? PLUGIN_DESCRIPTION_TRANSLATIONS[i18nLanguage]?.[value] ?? RECEIVER_TRANSLATIONS[i18nLanguage]?.[value] ?? RESCAN_TRANSLATIONS[i18nLanguage]?.[value] ?? BUNDLED_UI_TRANSLATIONS[i18nLanguage]?.[value] ?? HOST_ERROR_TRANSLATIONS[i18nLanguage]?.[value] ?? STATUS_TRANSLATIONS[i18nLanguage]?.[value] ?? GUI_STATUS_TRANSLATIONS[i18nLanguage]?.[value];
  if (exact !== undefined) return exact;
  if (typeof value !== "string") return value;
  const runtime = RUNTIME_TRANSLATIONS[i18nLanguage];
  if (runtime?.[value] !== undefined) return runtime[value];
  const catalogEntry = Object.entries(I18N_CATALOGS.en).find(([_key, english]) => english === value);
  if (catalogEntry) return i18nTranslate(catalogEntry[0]);
  const dynamic = DYNAMIC_TRANSLATIONS[i18nLanguage];
  if (dynamic) {
    const format = (template, variables) => template.replace(/\{(\w+)\}/g, (_whole, key) => variables[key] ?? "");
    const tutorial = /^1\. Open the Discord Developer Portal and create or select an application\.\n2\. Under OAuth2, add (.+) as an exact redirect URI\.\n3\. Reset the client secret, then paste the new secret below\.\n4\. Copy the application's Application ID below\.\n5\. Select Save and authorize, then approve only rpc, rpc\.voice\.read, and rpc\.voice\.write in Discord\.$/.exec(value);
    if (tutorial) return dynamic.tutorial.map(line => line.replace("{value}", tutorial[1])).join("\n");
    for (const [pattern, label] of [
      [/^Selected monitor: (.+)$/, dynamic.selectedMonitor],
      [/^Selected Bluetooth device: (.+)$/, dynamic.selectedBluetooth],
      [/^Selected capture input: (.+)$/, dynamic.selectedCapture],
      [/^Selected soundcard: (.+)$/, dynamic.selectedSoundcard],
      [/^Configured: (.+)$/, dynamic.configured],
    ]) {
      const match = pattern.exec(value);
      if (match) return `${label}: ${match[1]}`;
    }
    let match = /^Profile: (.+); Home Assistant: (.+); slider max: (\d+)\.$/.exec(value);
    if (match) return `${dynamic.profile}: ${match[1]}; ${dynamic.homeAssistant}: ${match[2]}; ${dynamic.sliderMax}: ${match[3]}.`;
    match = /^Broker: (.+); Home Assistant discovery: (.+); slider max: (\d+)\.$/.exec(value);
    if (match) return `${dynamic.broker}: ${match[1]}; ${dynamic.discovery}: ${match[2]}; ${dynamic.sliderMax}: ${match[3]}.`;
    match = /^OAuth status: (.+)\.$/.exec(value);
    if (match) return `${dynamic.oauthStatus}: ${i18nSource(match[1])}.`;
    match = /^(Active|Active after mouse movement): (.+)$/.exec(value);
    if (match) return `${match[1] === "Active" ? dynamic.activeTargets : dynamic.recentTargets}: ${match[2].split(", ").map(i18nSource).join(", ")}`;
    match = /^(Playback|Voice output) keep-alive failed: (.+)$/.exec(value);
    if (match) return `${i18nSource(match[1])} ${dynamic.keepAliveFailed}: ${match[2]}`;
    for (const [pattern, noun] of [
      [/^(\d+) configurable DDC monitor\(s\) found$/, dynamic.foundMonitors],
      [/^Found (\d+) configurable DDC monitor\(s\)$/, dynamic.foundMonitors],
      [/^(\d+) paired Bluetooth audio device\(s\) found\.$/, dynamic.foundPaired],
      [/^(\d+) render soundcard endpoint\(s\) found\.$/, dynamic.foundRender],
      [/^(\d+) capture endpoint\(s\) found\.$/, dynamic.foundCapture],
      [/^(\d+) monitor\(s\) found\.$/, dynamic.monitorFound],
    ]) {
      match = pattern.exec(value);
      if (match) return `${match[1]} ${noun}${value.endsWith(".") ? "." : ""}`;
    }
    match = /^Decrease: (.+); Increase: (.+?)(?:; Mute: (.+?))?\. (Keys remain forwarded to other apps\.|Configured keys are consumed while this route is active\.)$/.exec(value);
    if (match) return `${i18nSource("Decrease")}: ${i18nSource(match[1])}; ${i18nSource("Increase")}: ${i18nSource(match[2])}${match[3] ? `; ${i18nSource("Mute")}: ${i18nSource(match[3])}` : ""}. ${i18nSource(match[4])}`;
    for (const [pattern, template] of [
      [/^Configuration exported to (.+) and added to import history\.$/, dynamic.exportedHistory],
      [/^Configuration exported to (.+)\.$/, dynamic.exported],
      [/^Default configuration not found: (.+)\.$/, dynamic.defaultMissing],
      [/^Configuration imported from (.+)\. Restarting FenSoundSwitch\.\.\.$/, dynamic.imported],
      [/^Queued volume (\d+)%\.\.\.$/, dynamic.queuedVolume],
    ]) {
      match = pattern.exec(value);
      if (match) return format(template, { value: match[1] });
    }
    if (value === "Start with Windows enabled.") return dynamic.startEnabled;
    if (value === "Start with Windows disabled.") return dynamic.startDisabled;
    match = /^Ready\. Volume provider: (.+)\.$/.exec(value);
    if (match) return format(dynamic.readyProvider, { value: i18nSource(match[1]) });
    match = /^Ready\. (\d+) monitor\(s\) detected\. Volume keys control (.+)\.$/.exec(value);
    if (match) return format(dynamic.monitorsDetected, { count: match[1], name: match[2] });
    match = /^(.+) volume: (\d+)%$/.exec(value);
    if (match) return format(dynamic.selectedVolume, { name: match[1], value: match[2] });
  }
  if (runtime) {
    const formatRuntime = (template, variables) => template.replace(/\{(\w+)\}/g, (_whole, key) => variables[key] ?? "");
    let match = /^(Discord is not running or no local RPC pipe is available): (.*)$/.exec(value);
    // Pipe names and OS error details are opaque and must not be translated.
    if (match) return `${runtime[match[1]]}: ${match[2]}`;
    match = /^Route (.+) is unavailable: (.+)$/.exec(value);
    if (match) return formatRuntime(runtime.routeUnavailable, { name: match[1], detail: i18nSource(match[2]) });
    match = /^Automation (.+) trigger is unavailable(?:: (.+))?\.$/.exec(value);
    if (match) return formatRuntime(runtime.automationTriggerUnavailable, { name: match[1], detail: match[2] ? i18nSource(match[2]) : "" }).replace(/[:：]\s*$/, "");
    match = /^Automation (.+) trigger failed: (.+)$/.exec(value);
    if (match) return formatRuntime(runtime.automationTriggerFailed, { name: match[1], detail: i18nSource(match[2]) });
    match = /^Automation (.+) stopped: (.+)$/.exec(value);
    if (match) return formatRuntime(runtime.automationStopped, { name: match[1], detail: i18nSource(match[2]) });
    match = /^Plugin (.+) is unavailable: (.+)$/.exec(value);
    if (match) return formatRuntime(runtime.pluginUnavailable, { name: match[1], detail: i18nSource(match[2]) });
    match = /^(Could not communicate with the configured (?:AVR|Onkyo receiver|Pioneer\/Elite receiver|Sony receiver|Yamaha receiver)): (.*)$/.exec(value);
    if (match) {
      const wrapper = { "Could not communicate with the configured AVR": runtime.receiverAvr, "Could not communicate with the configured Onkyo receiver": runtime.receiverOnkyo, "Could not communicate with the configured Pioneer/Elite receiver": runtime.receiverPioneer, "Could not communicate with the configured Sony receiver": runtime.receiverSony, "Could not communicate with the configured Yamaha receiver": runtime.receiverYamaha }[match[1]];
      return `${wrapper}: ${match[2]}`;
    }
  }
  const endpoint = /^(Input|Output): (.+)$/.exec(value);
  if (endpoint) return `${i18nSource(endpoint[1])}: ${i18nSource(endpoint[2])}`;
  if (value.includes(" + ")) return value.split(" + ").map(i18nSource).join(" + ");
  const tray = /^Tray: (.+)$/.exec(value);
  if (tray) return `${i18nLanguage === "de" ? "Infobereich" : i18nLanguage === "es" ? "Bandeja" : i18nLanguage === "fr" ? "Zone de notification" : i18nLanguage === "it" ? "Area di notifica" : "Tray"}: ${tray[1]}`;
  const wait = /^wait ([0-9.]+)s$/.exec(value);
  if (wait) return `${i18nTranslate("editor.wait")} ${wait[1]} s`;
  if (value.includes("+") && !value.includes(" + ")) {
    const parts = value.split("+");
    const translated = parts.map(i18nSource);
    if (translated.some((part, index) => part !== parts[index])) return translated.join("+");
  }
  if (value.includes(" then ")) return value.split(" then ").map(i18nSource).join(i18nLanguage === "de" ? " dann " : i18nLanguage === "es" ? " después " : i18nLanguage === "fr" ? " puis " : i18nLanguage === "it" ? " poi " : " then ");
  if (value.includes("; ")) {
    const parts = value.split("; ");
    const first = i18nSource(parts[0]);
    if (first !== parts[0]) {
      const suffixes = parts.slice(1).map(part => {
        const shortcut = /^shortcut: (.+)$/.exec(part);
        return shortcut ? `${DECORATION_TRANSLATIONS[i18nLanguage]?.shortcut ?? "shortcut"}: ${shortcut[1]}` : DECORATION_TRANSLATIONS[i18nLanguage]?.[part] ?? i18nSource(part);
      });
      return [first, ...suffixes].join("; ");
    }
  }
  const colon = /^([^:]+): (.+)$/.exec(value);
  if (colon) {
    const pluginPrefix = /^Plugin (.+)$/.exec(colon[1]);
    const prefix = pluginPrefix ? `${i18nSource("Plugin")} ${i18nSource(pluginPrefix[1])}` : STATUS_PREFIX_TRANSLATIONS[i18nLanguage]?.[colon[1]] ?? i18nSource(colon[1]);
    let tail = i18nSource(colon[2]);
    if (tail === colon[2]) {
      const summarizedAction = /^(.+?) \((.*)\)$/.exec(colon[2]);
      if (summarizedAction) {
        const action = i18nSource(summarizedAction[1]);
        if (action !== summarizedAction[1]) tail = `${action} (${i18nSource(summarizedAction[2])})`;
      }
    }
    // Unknown tails remain byte-for-byte device, user, or exception text.
    if (prefix !== colon[1] || tail !== colon[2]) return `${prefix}: ${tail}`;
  }
  return value;
}

function i18nApplyStatic() {
  document.title = i18nTranslate("app.title");
  for (const node of document.querySelectorAll("[data-i18n]")) node.textContent = i18nTranslate(node.dataset.i18n);
  for (const node of document.querySelectorAll("[data-i18n-aria]")) node.setAttribute("aria-label", i18nTranslate(node.dataset.i18nAria));
  for (const node of document.querySelectorAll("[data-i18n-title]")) node.setAttribute("title", i18nTranslate(node.dataset.i18nTitle));
  for (const button of document.querySelectorAll("[data-page]")) {
    const text = button.lastChild;
    if (text?.nodeType === Node.TEXT_NODE) text.textContent = i18nTranslate(`nav.${button.dataset.page}`);
  }
  const textById = { "editor-back": "common.back", "editor-cancel": "common.cancel", "editor-save": "common.save", "choice-cancel": "common.cancel", "slot-refresh": "dialog.refreshMonitors", "slot-cancel": "common.cancel", "slot-save": "dialog.saveStep", "mqtt-add": "integration.add", "mqtt-back": "common.back", "mqtt-profile-cancel": "common.cancel", "mqtt-profile-save": "integration.save" };
  for (const [id, key] of Object.entries(textById)) {
    const node = document.getElementById(id);
    if (node) node.textContent = i18nTranslate(key);
  }
  for (const node of document.querySelectorAll(".icon-button[aria-label]")) node.setAttribute("aria-label", i18nTranslate("common.close"));
}

window.FenI18n = { applyStatic: i18nApplyStatic, setLanguage: i18nSetLanguage, source: i18nSource, t: i18nTranslate };
